#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 105
#define MAXL 10005
#define INF 1000000000

static char s[MAXN][MAXL];
static int len[MAXN];
static int N, K;

static int dp[MAXN + 2][MAXL];   // dp[i][r]: possible using suffix i..N to make length r
static char ans[MAXL];

/*
  Returns 1 if candidate string t (length rem) can be formed from strings i..N
  while preserving order and taking whole strings.
*/
static int can_form(int i, int rem) {
    if (rem < 0) return 0;
    if (i > N) return (rem == 0);
    return dp[i][rem];
}

int main(void) {
    if (scanf("%d %d", &N, &K) != 2) return 0;
    for (int i = 1; i <= N; i++) {
        scanf("%s", s[i]);
        len[i] = (int)strlen(s[i]);
    }

    /* DP for reachability of total lengths */
    for (int r = 0; r <= K; r++) dp[N + 1][r] = 0;
    dp[N + 1][0] = 1;

    for (int i = N; i >= 1; i--) {
        for (int r = 0; r <= K; r++) {
            dp[i][r] = dp[i + 1][r];
            if (r >= len[i] && dp[i + 1][r - len[i]]) dp[i][r] = 1;
        }
    }

    /*
      Greedy construction.

      State:
      - current answer prefix ans[0..pos-1]
      - among all ways to obtain this prefix, keep all possible states (i, off):
          we are currently at string i, having already consumed first off chars of s[i]
          as part of the answer prefix.
        Special case off == len[i] means next char must come from a later chosen string.
      We compress this by keeping reachable states after each chosen character.
    */

    static int cur_i[MAXN * MAXL / 10 + 1000], cur_off[MAXN * MAXL / 10 + 1000];
    static int nxt_i[MAXN * MAXL / 10 + 1000], nxt_off[MAXN * MAXL / 10 + 1000];
    int cur_cnt = 1;
    cur_i[0] = 1;
    cur_off[0] = 0;

    for (int pos = 0; pos < K; pos++) {
        char best = '{'; // one after 'z' in ASCII

        /*
          From each current state, try all possible next characters:
          - continue current string if off < len[i]
          - or start some later string j >= i if current string is finished/skipped
        */
        for (int idx = 0; idx < cur_cnt; idx++) {
            int i = cur_i[idx];
            int off = cur_off[idx];

            // Option 1: continue current string
            if (i <= N && off < len[i]) {
                int rem_after = K - (pos + 1);
                int need_from_suffix = rem_after - (len[i] - (off + 1));
                if (need_from_suffix >= 0 && can_form(i + 1, need_from_suffix)) {
                    if (s[i][off] < best) best = s[i][off];
                }
            }

            // Option 2: start some later string
            int startj = i;
            if (i <= N && off < len[i]) startj = i + 1; // cannot abandon a chosen string mid-way
            for (int j = startj; j <= N; j++) {
                if (len[j] == 0) continue;
                int rem_after = K - (pos + 1);
                int need_from_suffix = rem_after - (len[j] - 1);
                if (need_from_suffix >= 0 && can_form(j + 1, need_from_suffix)) {
                    if (s[j][0] < best) best = s[j][0];
                }
            }
        }

        ans[pos] = best;

        // Build next states achieving best
        int nxt_cnt = 0;

        for (int idx = 0; idx < cur_cnt; idx++) {
            int i = cur_i[idx];
            int off = cur_off[idx];

            // continue current string
            if (i <= N && off < len[i] && s[i][off] == best) {
                int rem_after = K - (pos + 1);
                int need_from_suffix = rem_after - (len[i] - (off + 1));
                if (need_from_suffix >= 0 && can_form(i + 1, need_from_suffix)) {
                    int ni = i, noff = off + 1;
                    int dup = 0;
                    for (int t = 0; t < nxt_cnt; t++) {
                        if (nxt_i[t] == ni && nxt_off[t] == noff) { dup = 1; break; }
                    }
                    if (!dup) {
                        nxt_i[nxt_cnt] = ni;
                        nxt_off[nxt_cnt] = noff;
                        nxt_cnt++;
                    }
                }
            }

            // start later string
            int startj = i;
            if (i <= N && off < len[i]) startj = i + 1;
            for (int j = startj; j <= N; j++) {
                if (len[j] == 0) continue;
                if (s[j][0] != best) continue;
                int rem_after = K - (pos + 1);
                int need_from_suffix = rem_after - (len[j] - 1);
                if (need_from_suffix >= 0 && can_form(j + 1, need_from_suffix)) {
                    int ni = j, noff = 1;
                    int dup = 0;
                    for (int t = 0; t < nxt_cnt; t++) {
                        if (nxt_i[t] == ni && nxt_off[t] == noff) { dup = 1; break; }
                    }
                    if (!dup) {
                        nxt_i[nxt_cnt] = ni;
                        nxt_off[nxt_cnt] = noff;
                        nxt_cnt++;
                    }
                }
            }
        }

        cur_cnt = nxt_cnt;
        for (int i = 0; i < cur_cnt; i++) {
            cur_i[i] = nxt_i[i];
            cur_off[i] = nxt_off[i];
        }
    }

    ans[K] = '\0';
    printf("%s\n", ans);
    return 0;
}

