    cin >> N >> K;
    vector<string> s(N);
    for (int i = 0; i < N; i++) {
        cin >> s[i];
    }

    // dp[i] = lexicographically smallest string of length exactly K 
    // using strings from i to N-1, or a sentinel if impossible.
    vector<string> dp(N + 1);
    dp[N] = string(K, 'z' + 1); // impossible marker (larger than any letter)

    for (int i = N - 1; i >= 0; i--) {
        string best = dp[i+1]; // skip s[i]
        int len = s[i].size();
        if (len <= K) {
            string take = s[i] + dp[i+1].substr(0, K - len);
            if (take < best) {
                best = take;
            }
        }
        dp[i] = best;
    }

    cout << dp[0] << "\n";

    return 0;
}

