int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<string> s(N + 1);
    for (int i = 1; i <= N; i++) cin >> s[i];

    const string INF(10005, '{'); // larger than lowercase strings

    // dp[i][j] = lexicographically smallest string of length j
    // obtainable using strings from i..N
    vector<vector<string>> dp(N + 2, vector<string>(K + 1, INF));

    dp[N + 1][0] = "";
    for (int j = 1; j <= K; j++) dp[N + 1][j] = INF;

    for (int i = N; i >= 1; i--) {
        for (int j = 0; j <= K; j++) {
            // skip s[i]
            dp[i][j] = dp[i + 1][j];

            // take s[i]
            int len = (int)s[i].size();
            if (j >= len && dp[i + 1][j - len] != INF) {
                string cand = s[i] + dp[i + 1][j - len];
                if (cand < dp[i][j]) dp[i][j] = cand;
            }
        }
    }

    cout << dp[1][K] << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        sc.nextLine(); // consume newline
        String[] s = new String[N];
        for (int i = 0; i < N; i++) {
            s[i] = sc.nextLine();
        }

        // dp[i] = minimum length that can be formed from index i
        int[] minLen = new int[N + 1];
        int[] maxLen = new int[N + 1];
        minLen[N] = maxLen[N] = 0;
        for (int i = N - 1; i >= 0; i--) {
            minLen[i] = minLen[i + 1] + s[i].length();
            maxLen[i] = maxLen[i + 1] + s[i].length();
        }

        // We'll build the answer character by character
        StringBuilder ans = new StringBuilder();
        int pos = 0; // current position in s array
        int need = K; // how many more characters we need

        while (need > 0) {
            // Try to pick the best starting string from pos onward
            for (int i = pos; i < N; i++) {
                // We must be able to pick from this string
                int takeLen = Math.min(s[i].length(), need);
                if (takeLen == 0) continue;
                // Check if it's possible to complete after taking from this string
                int afterMin = minLen[i + 1];
                int afterMax = maxLen[i + 1];
                if (need - takeLen < afterMin || need - takeLen > afterMax) {
                    continue;
                }
                // Try to take as few characters as possible to get smallest char
                for (int take = 1; take <= takeLen; take++) {
                    if (need - take >= minLen[i + 1] && need - take <= maxLen[i + 1]) {
                        ans.append(s[i].substring(0, take));
                        need -= take;
                        pos = i + 1;
                        break;
                    }
                }
                break;
            }
        }

        System.out.println(ans.toString());
    }
}

