public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        String[] s = new String[N];
        for (int i = 0; i < N; i++) s[i] = br.readLine().trim();

        // possible[i][j] = can we form exactly j chars from strings i..N-1
        boolean[][] possible = new boolean[N+1][K+1];
        possible[N][0] = true;
        for (int i = N-1; i >= 0; i--) {
            int len = s[i].length();
            for (int j = 0; j <= K; j++) {
                possible[i][j] = possible[i+1][j]; // skip
                if (j >= len && possible[i+1][j-len]) possible[i][j] = true; // take
            }
        }

        StringBuilder sb = new StringBuilder();
        int si = 0; // current string index
        int sp = 0; // position within current string (if we're inside one)
        boolean inString = false;
        int rem = K;

        while (rem > 0) {
            if (inString) {
                sb.append(s[si].charAt(sp));
                rem--;
                sp++;
                if (sp == s[si].length()) { si++; inString = false; sp = 0; }
            } else {
                // Find smallest char we can place at this position
                // Try each possible string si..N-1 to start with
                // We need to pick string si' >= si to start, take it, and be able to complete rem chars
                char best = (char)('z'+1);
                for (int i = si; i < N; i++) {
                    if (s[i].length() <= rem && possible[i+1][rem - s[i].length()]) {
                        if (s[i].charAt(0) < best) best = s[i].charAt(0);
                    }
                }
                // Now find the latest si we can skip to, starting a string with 'best'
                // Actually pick the first valid string with that char, but we want to skip as many as possible before it
                // We need: skip si..i-1, take s[i] starting with best
                // Find smallest i >= si such that s[i][0]==best and valid
                for (int i = si; i < N; i++) {
                    if (s[i].length() <= rem && possible[i+1][rem - s[i].length()] && s[i].charAt(0) == best) {
                        si = i; inString = true; sp = 0; break;
                    }
                }
            }
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
