public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int K = fs.nextInt();

        String[] s = new String[N + 1];
        int[] len = new int[N + 1];
        int[] suffixSum = new int[N + 2];

        for (int i = 1; i <= N; i++) {
            s[i] = fs.next();
            len[i] = s[i].length();
        }

        for (int i = N; i >= 1; i--) {
            suffixSum[i] = suffixSum[i + 1] + len[i];
        }

        // dp[i][j] = lexicographically smallest string of length j
        // obtainable by choosing from s_i ... s_N in order.
        String[][] dp = new String[N + 2][K + 1];

        for (int i = 1; i <= N + 1; i++) dp[i][0] = "";
        for (int j = 1; j <= K; j++) dp[N + 1][j] = null;

        for (int i = N; i >= 1; i--) {
            for (int j = 1; j <= K; j++) {
                String best = null;

                // Skip s[i]
                if (suffixSum[i + 1] >= j) {
                    best = dp[i + 1][j];
                }

                // Take s[i]
                if (j >= len[i] && suffixSum[i + 1] >= j - len[i]) {
                    String tail = dp[i + 1][j - len[i]];
                    if (tail != null) {
                        String cand = s[i] + tail;
                        if (best == null || cand.compareTo(best) < 0) {
                            best = cand;
                        }
                    }
                }

                dp[i][j] = best;
            }
        }

        System.out.println(dp[1][K]);
    }
}
